"""Trusted scope binding and bounded prompt construction for agent graphs."""
import hashlib
import os
from langchain_core.messages import SystemMessage, HumanMessage, AIMessage, ToolMessage
from langgraph.prebuilt import ToolNode


def auth_headers():
    token=os.environ.get('MEMORY_API_TOKEN','')
    if not token: raise RuntimeError('MEMORY_API_TOKEN is required')
    return {'Authorization':f'Bearer {token}'}


def refresh_messages(system_content, existing, user_text):
    # IDs are stable so add_messages replaces the prior system prompt.
    old=next((m for m in existing if m.type=='system'),None)
    return [SystemMessage(content=system_content[:20000],id=old.id if old else 'memory-system'),HumanMessage(content=user_text)]


def prompt_messages(messages, max_chars=32000):
    """Select complete conversational turns; never truncate a tool-call/result pair."""
    systems=[m for m in messages if m.type=='system']
    turns=[]
    for m in messages:
        if m.type=='system': continue
        if m.type=='human' or not turns: turns.append([])
        turns[-1].append(m)
    selected=[]
    budget=max_chars-sum(len(str(m.content)) for m in systems[-1:])
    for turn in reversed(turns):
        size=sum(len(str(m.content))+len(str(getattr(m,'tool_calls',[]))) for m in turn)
        if size>budget:
            if not selected: raise ValueError('Current turn exceeds the context budget')
            break
        selected=turn+selected; budget-=size
    return systems[-1:]+selected


def bound_args(state, args):
    result=dict(args)
    for key in ('user_id','project_id','git_branch','user_role','workflow_id','agent_id','agent_name'):
        if key in state and key in result: result[key]=state[key]
    if 'allowed_role' in result and 'user_role' in state:
        result['allowed_role']=state['user_role']
    if 'agent_id' in state:
        result.setdefault('agent_id',state['agent_id'])
    return result


class ScopedToolNode:
    def __init__(self, tools):
        self.node=ToolNode(tools)
    async def __call__(self, state, config):
        last=state['messages'][-1]
        calls=[dict(tc,args=bound_args(state,tc['args'])) for tc in last.tool_calls]
        # Deletion is exclusive within a tool batch. Never dispatch sibling writes.
        forget=next((c for c in calls if c['name']=='forget_companion_memory'),None)
        if forget:
            response=await self.node.ainvoke(dict(state,messages=[last.model_copy(update={'tool_calls':[forget]})]),config)
            result=response['messages'][0]
            failed=getattr(result,'status',None)=='error' or not str(result.content).startswith('Memory forgotten')
            if failed:
                return {'messages':response['messages']+[ToolMessage(content='Cancelled because deletion failed',tool_call_id=c['id']) for c in calls if c is not forget]}
            return {'forgotten':True, 'messages':response['messages']+[ToolMessage(content='Cancelled by forget request',tool_call_id=c['id']) for c in calls if c is not forget]+[AIMessage(content='Your stored memory has been deleted. Memory recording is disabled until you explicitly resume it.')]}
        return await self.node.ainvoke(dict(state,messages=[last.model_copy(update={'tool_calls':calls})]),config)


class ScopedGraph:
    """Namespace checkpoints using application-owned input scope, never tool arguments."""
    def __init__(self, graph, domain, saver=None):
        self.graph,self.domain,self.saver=graph,domain,saver
    def __getattr__(self,name): return getattr(self.graph,name)
    async def ainvoke(self, state, config=None, **kwargs):
        config=dict(config or {}); settings=dict(config.get('configurable',{}))
        if self.domain=='companion':
            identity=state['user_id']
            settings['memory_user_id']=identity
        else:
            import json
            identity=json.dumps({k:state[k] for k in ('user_id','project_id','git_branch','user_role','workflow_id','agent_id') if k in state},sort_keys=True)
        thread=settings.get('thread_id','default')
        settings['thread_id']=f'{self.domain}:{hashlib.sha256(identity.encode()).hexdigest()}:{thread}'
        config['configurable']=settings
        result=await self.graph.ainvoke(state,config,**kwargs)
        if result.get('forgotten'):
            if self.saver:
                await self.saver.adelete_thread(settings['thread_id'])
            return {'user_id':identity,'forgotten':True,'messages':[AIMessage(content='Your stored memory has been deleted. Memory recording is disabled until you explicitly resume it.')]}
        return result
